css:
body {
  font-family: Arial, sans-serif;
  font-size: 10pt;
  padding: 20px;
}
.header {
  text-align: center;
  border-bottom: 2px solid #333;
  padding-bottom: 10px;
  margin-bottom: 20px;
}
.title {
  font-size: 16pt;
  font-weight: bold;
  color: #2c3e50;
}
.info-table {
  width: 100%;
  border-collapse: collapse;
  margin-bottom: 15px;
}
.info-table td {
  padding: 8px;
  border: 1px solid #ddd;
  vertical-align: top;
}
.label {
  font-weight: bold;
  background: #f0f0f0;
  width: 30%;
}
.goods-table {
  width: 100%;
  border-collapse: collapse;
  margin-bottom: 15px;
}
.goods-table th {
  background: #2c3e50;
  color: white;
  padding: 8px;
  text-align: left;
}
.goods-table td {
  padding: 8px;
  border-bottom: 1px solid #ddd;
}
.signature {
  margin-top: 50px;
  border-top: 1px solid #333;
  width: 200px;
  padding-top: 10px;
}
.footer {
  text-align: center;
  margin-top: 30px;
  font-size: 8pt;
  color: #666;
  border-top: 1px solid #ddd;
  padding-top: 10px;
}

